Problem Description:
Module A implements the boolean function z = (x^y) & x.

// Module B can be described by the following simulation waveform: 

// time            x               y               z               
// 0ns             0               0               1               
// 5ns             0               0               1               
// 10ns            0               0               1               
// 15ns            0               0               1               
// 20ns            0               0               1               
// 25ns            1               0               0               
// 30ns            1               0               0               
// 35ns            0               1               0               
// 40ns            0               1               0               
// 45ns            1               1               1               
// 50ns            1               1               1               
// 55ns            0               0               1               
// 60ns            0               1               0               
// 65ns            0               1               0               
// 70ns            1               1               1               
// 75ns            0               1               0               
// 80ns            0               1               0               
// 85ns            0               1               0               
// 90ns            1               0               0               


// Now consider a top-level that uses two A submodules and two B submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first A submodule is connected to a two-input OR, along with the output of the first B submodule. The second pair of A and B submodules is similarly connected to an AND gate. The output of the OR and the AND is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
	input x,
	input y,
	output z);

Erroneous Implementation:

wire a1_out, b1_out, a2_out, b2_out, or_out, and_out, xor_out;

	A a1(.x(x), .y(y), .z(a1_out));
	B b1(.x(x), .y(y), .z(b1_out));
	A a2(.x(x), .y(y), .z(a2_out));
	B b2(.x(x), .y(y), .z(b2_out));

	or or_gate(.a(a1_out), .b(b1_out), .out(or_out));
	and and_gate(.a(a2_out), .b(b2_out), .out(and_out));

	xor xor_gate(.a(or_out), .b(and_out), .out(xor_out));

	assign z = xor_out;

endmodule

Feedback:
mt2015_q4.sv:130: error: Gates do not have port names.
mt2015_q4.sv:131: error: Gates do not have port names.
mt2015_q4.sv:133: error: Gates do not have port names.

